while (count > 0) {
    int cell = (int)(Pop(heap, ref count) & 0xFFFFF);
    if (nodes[cell].Closed == search) continue;
    nodes[cell].Closed = search;
    int g = nodes[cell].G;
    if (cell == goal) return g + 1;
    int r = cell / n, c = cell % n;
    for (int dr = -1; dr <= 1; dr++)
        for (int dc = -1; dc <= 1; dc++) {
            int y = r + dr, x = c + dc;
            if ((dr | dc) == 0 || y < 0 || x < 0 || y >= n || x >= n || grid[y][x] == 1) continue;
            int next = y * n + x;
            ref Node nb = ref nodes[next];
            if (nb.Closed != 0) continue;                       // closed
            if (nb.Opened == search && nb.G <= g + 1) continue;
            nb.G = g + 1;
            nb.Opened = search;
            Push(heap, ref count, Key(g + 1 + H(next, n), H(next, n), next));
        }
}

